const fixtureTranscript = `{"type":"assistant","timestamp":"2026-04-15T10:00:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"ls -la"}}]}}
{"type":"user","timestamp":"2026-04-15T10:01:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"x"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:02:00Z","message":{"content":[{"type":"text","text":"let me think"},{"type":"tool_use","name":"Edit","input":{"file_path":"foo.go"}}]}}
{"type":"user","timestamp":"2026-04-15T10:03:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"y"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:04:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"git commit -m foo"}}]}}
`

func TestDeriveToolTime_BasicCounts(t *testing.T) {
	t.Parallel()
	profile, err := DeriveToolTime(strings.NewReader(fixtureTranscript))
	if err != nil {
		t.Fatal(err)
	}
	if profile == nil {
		t.Fatal("nil profile")
	}
	if got := profile.Categories[CategoryShell].Count; got != 1 {
		t.Errorf("shell count = %d, want 1", got)
	}
	if got := profile.Categories[CategoryFileOps].Count; got != 1 {
		t.Errorf("fileOps count = %d, want 1", got)
	}
	if got := profile.Categories[CategoryCommit].Count; got != 1 {
		t.Errorf("commit count = %d, want 1", got)
	}
	if profile.Total != 3 {
		t.Errorf("total = %d, want 3", profile.Total)
	}
}

func TestDeriveToolTime_Durations(t *testing.T) {
	t.Parallel()
	profile, err := DeriveToolTime(strings.NewReader(fixtureTranscript))
	if err != nil {
		t.Fatal(err)
	}
	if got := profile.Categories[CategoryShell].DurationMs; got != 120_000 {
		t.Errorf("shell duration = %d ms, want 120000", got)
	}
	if got := profile.Categories[CategoryFileOps].DurationMs; got != 120_000 {
		t.Errorf("fileOps duration = %d ms, want 120000", got)
	}
	if got := profile.Categories[CategoryCommit].DurationMs; got != 0 {
		t.Errorf("commit duration = %d, want 0 (no successor)", got)
	}
}

func TestDeriveToolTime_ConversationBucket(t *testing.T) {
	t.Parallel()
	profile, err := DeriveToolTime(strings.NewReader(fixtureTranscript))
	if err != nil {
		t.Fatal(err)
	}
	if got := profile.Categories[CategoryConversation].DurationMs; got < 50_000 || got > 70_000 {
		t.Errorf("conversation duration = %d, want ~60000", got)
	}
}

func TestDeriveToolTime_EmptyTranscript(t *testing.T) {
	t.Parallel()
	profile, err := DeriveToolTime(strings.NewReader(""))
	if err != nil {
		t.Fatal(err)
	}
	if profile == nil {
		t.Fatal("nil profile for empty transcript")
	}
	if profile.Total != 0 {
		t.Errorf("expected zero total, got %d", profile.Total)
	}
}

package activity

import (
	"bufio"
	"encoding/json"
	"io"
	"time"
)

// DeriveToolTime walks a JSONL transcript (Claude Code / Cursor shape) and
// returns a ToolProfile with per-category counts and durations. Duration
// semantics: time between the start of one tool_use and the start of the
// next. This is "time between tool calls", NOT pure tool execution time —
// it includes agent thinking. Label accordingly when rendering.
//
// The virtual `conversation` category captures the gap between a
// tool_result and the following tool_use when the assistant produced text
// in that gap. The virtual `commit` category catches Bash commands
// starting with `git commit` or `git push` (via CategorizeTool).
func DeriveToolTime(r io.Reader) (*ToolProfile, error) {
	profile := &ToolProfile{Categories: map[string]ToolCategoryMetrics{}}

	type pending struct {
		category string
		at       time.Time
	}
	var lastToolUse *pending
	var lastToolResultAt *time.Time
	var assistantTextSinceResult bool

	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1<<20), 1<<24)

	type line struct {
		Type      string    `json:"type"`
		Timestamp time.Time `json:"timestamp"`
		Message   struct {
			Content []struct {
				Type  string          `json:"type"`
				Name  string          `json:"name,omitempty"`
				Text  string          `json:"text,omitempty"`
				Input json.RawMessage `json:"input,omitempty"`
			} `json:"content"`
		} `json:"message"`
	}

	for scanner.Scan() {
		var l line
		if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
			continue
		}
		for _, c := range l.Message.Content {
			switch c.Type {
			case "tool_use":
				cmd := bashCommandFromInput(c.Input)
				category := CategorizeTool(c.Name, cmd)

				if lastToolUse != nil {
					if d := l.Timestamp.Sub(lastToolUse.at); d > 0 {
						addDuration(profile, lastToolUse.category, d)
					}
				}
				if lastToolResultAt != nil && assistantTextSinceResult {
					if d := l.Timestamp.Sub(*lastToolResultAt); d > 0 {
						addDuration(profile, CategoryConversation, d)
					}
				}
				incrementCount(profile, category)
				lastToolUse = &pending{category: category, at: l.Timestamp}
				lastToolResultAt = nil
				assistantTextSinceResult = false
			case "tool_result":
				ts := l.Timestamp
				lastToolResultAt = &ts
				assistantTextSinceResult = false
			case "text":
				if lastToolResultAt != nil {
					assistantTextSinceResult = true
				}
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return profile, err
	}
	return profile, nil
}

func bashCommandFromInput(raw json.RawMessage) string {
	var v struct {
		Command string `json:"command,omitempty"`
	}
	_ = json.Unmarshal(raw, &v)
	return v.Command
}

func incrementCount(p *ToolProfile, category string) {
	m := p.Categories[category]
	m.Count++
	p.Categories[category] = m
	p.Total++
}

func addDuration(p *ToolProfile, category string, d time.Duration) {
	m := p.Categories[category]
	m.DurationMs += d.Milliseconds()
	p.Categories[category] = m
}

