70		rules := BuiltInFocusAreaRules()
71		if repoLocal, err := LoadFocusAreaConfig(worktreeRoot); err != nil {
72			logging.Warn(ctx, "activity: failed to load .entire/activity_areas.json, using built-in rules",
73				"error", err.Error())
74		} else if len(repoLocal) > 0 {
75			// Prepend repo-local rules so they win on equal priority; the
76			// rule engine's priority comparison handles the ordering.
77			rules = append(repoLocal, rules...)
78		}
79	
80		out := &Activity{Source: SourceLocal}
81		for _, s := range states {
82			out.Sessions = append(out.Sessions, projectSession(s, rules))
83		}
84	
85		// Attach committed checkpoints to the projected sessions. A fresh
86		// repo with no metadata branch is a valid state, so errors here
87		// degrade to "no checkpoints" rather than fail the whole load.
88		committed, err := strategy.ListCheckpoints(ctx)
89		if err != nil {
90			logging.Warn(ctx, "activity: failed to list committed checkpoints, continuing without them",
91				"error", err.Error())
92			committed = nil
93		}
94		bySession := map[string][]ActivityCheckpoint{}
95		for _, cp := range committed {
96			sids := cp.SessionIDs
97			if len(sids) == 0 && cp.SessionID != "" {
98				// Defensive: should always be populated for current metadata shape,
99				// but older or malformed metadata may omit it.
100				sids = []string{cp.SessionID}
101			}
102			// Dedupe defensively — a well-formed CheckpointInfo won't list the
103			// same session ID twice, but a malformed one would otherwise cause
104			// double-counting in SpanMinutes and len(Checkpoints).
105			seen := map[string]bool{}
106			for _, sid := range sids {
107				if sid == "" || seen[sid] {
108					continue
109				}
110				seen[sid] = true
111				bySession[sid] = append(bySession[sid], projectCheckpoint(cp, sid, rules))
112			}
113		}
114		for i := range out.Sessions {
115			sid := out.Sessions[i].SessionID
116			out.Sessions[i].Checkpoints = bySession[sid]
117		}
118	
119		// Collect committed checkpoint IDs (skip empty).
120		ids := []string{}
121		for _, s := range out.Sessions {
122			for _, cp := range s.Checkpoints {
123				if id := cp.ID.String(); id != "" {
124					ids = append(ids, id)
125				}
126			}
127		}
128		linked := LookupLinkedCommits(ctx, ids)
129	
130		for i := range out.Sessions {
131			var sessionLinked []string
132			for j, cp := range out.Sessions[i].Checkpoints {
133				shas := linked[cp.ID.String()]
134				if len(shas) > 0 {
135					out.Sessions[i].Checkpoints[j].LinkedCommit = shas[0]
136					sessionLinked = append(sessionLinked, shas...)
137				}
138			}
139			out.Sessions[i].LinkedCommits = dedupStrings(sessionLinked)
140		}
141	
142		// Group sessions by branch (empty-branch sessions form their own group).
143		// Then sort each group by StartedAt ascending so priorSameBranch slices
144		// are oldest-first.
145		sort.Slice(out.Sessions, func(i, j int) bool {
146			return out.Sessions[i].StartedAt.Before(out.Sessions[j].StartedAt)
147		})
148		byBranch := map[string][]int{} // branch → indices into out.Sessions, oldest first
149		for i, s := range out.Sessions {
150			byBranch[s.Branch] = append(byBranch[s.Branch], i)
151		}
152		for _, indices := range byBranch {
153			for pos, idx := range indices {
154				priors := make([]ActivitySession, 0, pos)
155				for _, pi := range indices[:pos] {
156					priors = append(priors, out.Sessions[pi])
157				}
158				out.Sessions[idx].Badges = ComputeBadges(out.Sessions[idx], priors)
159			}
160		}
161	
162		if opts.EnrichFromAPI && opts.Scope != ScopeLocal {
163			enricher := buildEnricher(ctx, opts)
164			if enricher != nil {
165				enrichSessionsInPlace(ctx, enricher, out.Sessions)
166			}
167		}
168		return out, nil
169	}
170	
171	// defaultTokenProvider reads from the OS keyring via auth.LookupCurrentToken.
172	// Used when LoadOpts.TokenProvider is nil.
173	func defaultTokenProvider() (string, error) {
174		tok, err := auth.LookupCurrentToken()
175		if err != nil {
176			return "", fmt.Errorf("lookup auth token: %w", err)
177		}
178		return tok, nil
179	}
180	
181	// buildEnricher returns an Enricher if a token is available. Returns
182	// nil when no token — callers treat that as "enrichment off."
183	//
184	// Respects opts.InsecureHTTP: in secure mode, refuses to build against
185	// a non-HTTPS BaseURL.
186	func buildEnricher(ctx context.Context, opts LoadOpts) *Enricher {
187		provider := opts.TokenProvider
188		if provider == nil {
189			provider = defaultTokenProvider
190		}
191		token, err := provider()
192		if err != nil {
193			logging.Debug(ctx, "activity: token lookup failed; enrichment disabled",
194				"error", err.Error())
195			return nil
196		}
197		if token == "" {
198			logging.Debug(ctx, "activity: no auth token; enrichment disabled")
199			return nil
200		}
201		if !opts.InsecureHTTP {
202			if err := api.RequireSecureURL(api.BaseURL()); err != nil {
203				// Security-relevant: refuse plain-HTTP endpoints in production.
204				logging.Warn(ctx, "activity: refusing enrichment against non-HTTPS endpoint",
205					"base_url", api.BaseURL(), "error", err.Error())
206				return nil
207			}
208		}
209		client := api.NewClient(token)
210		gitCommonDir, err := strategy.GetGitCommonDir(ctx)
211		if err != nil {
212			logging.Debug(ctx, "activity: GetGitCommonDir failed; enriching without cache",
213				"error", err.Error())
214			return NewEnricher(client, nil)
215		}
216		cache, err := NewAnalysisCache(gitCommonDir)
217		if err != nil {
218			logging.Debug(ctx, "activity: cache construction failed; enriching without cache",
219				"error", err.Error())
220			return NewEnricher(client, nil)
221		}
222		return NewEnricher(client, cache)
223	}
224	
225	// enrichSessionsInPlace mutates the checkpoints of each session, setting
226	// Labels and ToolProfile from the api when available. Each checkpoint
227	// fetches independently; failures don't block others.
228	func enrichSessionsInPlace(ctx context.Context, e *Enricher, sessions []ActivitySession) {
229		for si := range sessions {
230			for ci := range sessions[si].Checkpoints {
231				enriched, err := e.EnrichCheckpoint(ctx, sessions[si].Checkpoints[ci])
232				if err != nil {
233					// Non-fatal: EnrichCheckpoint reserves error for future
234					// conditions; current failures are logged internally.
235					logging.Debug(ctx, "activity: enrichment returned error",
236						"checkpoint", sessions[si].Checkpoints[ci].ID.String(),
237						"error", err.Error())
238				}
239				sessions[si].Checkpoints[ci] = enriched
240			}
241			// Roll session-level Labels up from its checkpoints.
242			sessions[si].Labels = rollupLabels(sessions[si].Checkpoints)
243			if sessionHasServerData(sessions[si].Checkpoints) {
244				sessions[si].Source = SourceMixed
245			}
246		}
247	}
248	
249	func rollupLabels(cps []ActivityCheckpoint) []string {
250		seen := map[string]bool{}
251		out := []string{}
252		for _, cp := range cps {
253			for _, l := range cp.Labels {
254				if seen[l] {
255					continue
256				}
257				seen[l] = true
258				out = append(out, l)
259			}
260		}
261		sort.Strings(out)
262		return out
263	}
264	
265	func sessionHasServerData(cps []ActivityCheckpoint) bool {
266		for _, cp := range cps {
267			if cp.Source == SourceMixed || cp.Source == SourceServer {
268				return true
269			}
270		}
271		return false
272	}
273	
274	// dedupStrings returns the input slice with duplicates removed while
275	// preserving insertion order.
276	func dedupStrings(ss []string) []string {
277		seen := map[string]bool{}
278		out := make([]string, 0, len(ss))
279		for _, s := range ss {
280			if seen[s] {
281				continue
282			}
283			seen[s] = true
284			out = append(out, s)
285		}
286		return out
287	}
288	
289	// projectSession turns a session.State into an ActivitySession projection.
290	// No i/o; safe to unit-test with in-memory fixtures.
291	//
292	// Field sources (verified in session/state.go and strategy/manual_commit_types.go):
293	//
294	//	SessionID, BaseCommit, WorktreeID, WorktreePath, StartedAt,
295	//	EndedAt (*time.Time), Phase (session.Phase), FilesTouched,
296	//	LastInteractionTime (*time.Time), StepCount, AgentType, ModelName,
297	//	TokenUsage
298	//
299	// Branch is NOT a session.State field — deferred to Chunk 2 when we
300	// derive it from the shadow-branch name or the checkpoint commit.
301	func projectSession(s *strategy.SessionState, rules []FocusAreaRule) ActivitySession {
302		out := ActivitySession{
303			SessionID:    s.SessionID,
304			BaseCommit:   s.BaseCommit,
305			WorktreeID:   s.WorktreeID,
306			WorktreePath: s.WorktreePath,
307			StartedAt:    s.StartedAt,
308			EndedAt:      s.EndedAt,
309			Phase:        s.Phase,
310			FilesTouched: append([]string(nil), s.FilesTouched...),
311			FocusAreas:   ResolveFocusAreas(rules, s.FilesTouched),
312			TokenUsage:   s.TokenUsage,
313			IsActive:     s.EndedAt == nil,
314			Source:       SourceLocal,
315		}
316		if s.LastInteractionTime != nil {
317			out.LastInteraction = *s.LastInteractionTime
318		}
319		if s.AgentType != "" {
320			out.AgentsUsed = []string{string(s.AgentType)}
321		}
322		if s.ModelName != "" {
323			out.ModelsUsed = []string{s.ModelName}
324		}
325		return out
326	}
327	
328	// projectCheckpoint turns a strategy.CheckpointInfo into an ActivityCheckpoint
329	// scoped to one session ID. When a checkpoint condensed multiple sessions, the
330	// caller invokes this once per session ID so each projected session gets its
331	// own copy. No i/o.
332	func projectCheckpoint(info strategy.CheckpointInfo, sid string, rules []FocusAreaRule) ActivityCheckpoint {
333		return ActivityCheckpoint{
334			ID:           info.CheckpointID,
335			SessionID:    sid,
336			CreatedAt:    info.CreatedAt,
337			FilesTouched: append([]string(nil), info.FilesTouched...),
338			FocusAreas:   ResolveFocusAreas(rules, info.FilesTouched),
339			Source:       SourceLocal,
340		}
341	}
