	loadLocalToolTime(ctx, &out.Sessions[i], transcriptBySID[out.Sessions[i].SessionID])
}

// loadLocalToolTime derives a session-level ToolProfile from the live
// transcript for active (un-ended) sessions. Silently skipped for ended
// sessions (server enrichment owns that case) and when the transcript
// file is missing or malformed — activity rendering tolerates nil.
func loadLocalToolTime(ctx context.Context, s *ActivitySession, transcriptPath string) {
	if !s.IsActive || transcriptPath == "" {
		return
	}
	f, err := os.Open(transcriptPath)
	if err != nil {
		logging.Debug(ctx, "activity: transcript unavailable; skipping local tool-time",
			"session", s.SessionID, "error", err.Error())
		return
	}
	defer f.Close()
	profile, err := DeriveToolTime(f)
	if err != nil {
		logging.Debug(ctx, "activity: DeriveToolTime failed; skipping local tool-time",
			"session", s.SessionID, "error", err.Error())
		return
	}
	if profile == nil || profile.Total == 0 {
		return
	}
	s.ToolProfile = profile
}

