// Throwaway demo that exercises the chunk-1 and chunk-2 activity layers.
// Not committed — delete after inspection.
package main

import (
	"context"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/activity"
)

func main() {
	ctx := context.Background()

	section("CHUNK 1 — Local data layer")
	demoLoadLocal(ctx)

	section("CHUNK 2a — Tool-name categorizer (Task 15)")
	demoCategorizer()

	section("CHUNK 2b — DeriveToolTime on a synthetic transcript (Task 16)")
	demoDeriveToolTime()

	section("CHUNK 2c — Session-level ToolProfile from live transcripts (Task 17)")
	demoSessionToolProfiles(ctx)

	section("CHUNK 2d — API enrichment with graceful offline fallback (Tasks 11–14)")
	demoEnrichment(ctx)
}

func section(title string) {
	fmt.Println()
	fmt.Println(strings.Repeat("═", 72))
	fmt.Println(title)
	fmt.Println(strings.Repeat("═", 72))
}

// ----- CHUNK 1 -----

func demoLoadLocal(ctx context.Context) {
	out, err := activity.LoadActivity(ctx, activity.LoadOpts{
		Scope: activity.ScopeLocal,
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, "ERROR:", err)
		os.Exit(1)
	}

	fmt.Printf("Source: %s\n", out.Source)
	fmt.Printf("Sessions: %d\n\n", len(out.Sessions))

	for i, s := range out.Sessions {
		if i >= 5 {
			fmt.Printf("... and %d more sessions\n", len(out.Sessions)-5)
			break
		}
		fmt.Printf("[%d] %s\n", i+1, s.SessionID)
		fmt.Printf("    started:   %s\n", s.StartedAt.Local().Format("2006-01-02 15:04"))
		fmt.Printf("    phase:     %s\n", s.Phase)
		fmt.Printf("    worktree:  %s\n", s.WorktreeID)
		fmt.Printf("    agent:     %v\n", s.AgentsUsed)
		fmt.Printf("    checkpts:  %d   span: %.1fm\n", len(s.Checkpoints), s.SpanMinutes())
		fmt.Printf("    linked:    %d commit(s)\n", len(s.LinkedCommits))
		fmt.Printf("    focus:     %v\n", s.FocusAreas)
		fmt.Printf("    badges:    %v\n", s.Badges)
