// ----- CHUNK 2a: CategorizeTool -----

func demoCategorizer() {
	cases := []struct {
		tool, bash string
	}{
		{"Bash", "ls -la"},
		{"Bash", "git commit -m foo"},
		{"Bash", "git push origin main"},
		{"Bash", "git status"},
		{"Edit", ""},
		{"Write", ""},
		{"Read", ""},
		{"Grep", ""},
		{"Glob", ""},
		{"Agent", ""},
		{"mcp__linear-server__list_issues", ""},
		{"WebFetch", ""},
		{"UnknownTool", ""},
	}
	fmt.Printf("  %-42s  %-16s  category\n", "tool", "bash command")
	fmt.Printf("  %s\n", strings.Repeat("─", 78))
	for _, c := range cases {
		fmt.Printf("  %-42s  %-16s  %s\n", c.tool, truncate(c.bash, 16), activity.CategorizeTool(c.tool, c.bash))
	}
	fmt.Println()
	fmt.Printf("Rendering order (AllCategories): %v\n", activity.AllCategories())
}

// ----- CHUNK 2b: DeriveToolTime -----

func demoDeriveToolTime() {
	// Same fixture shape used by tool_time_test.go — 5 JSONL lines, 60s gaps.
	transcript := `{"type":"assistant","timestamp":"2026-04-15T10:00:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"ls -la"}}]}}
{"type":"user","timestamp":"2026-04-15T10:01:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"x"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:02:00Z","message":{"content":[{"type":"text","text":"let me think"},{"type":"tool_use","name":"Edit","input":{"file_path":"foo.go"}}]}}
{"type":"user","timestamp":"2026-04-15T10:03:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"y"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:04:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"git commit -m foo"}}]}}
`
	profile, err := activity.DeriveToolTime(strings.NewReader(transcript))
	if err != nil {
		fmt.Fprintln(os.Stderr, "DeriveToolTime error:", err)
		return
	}
	fmt.Printf("Total tool uses: %d\n", profile.Total)
	fmt.Printf("  %-16s  count  duration\n", "category")
	fmt.Printf("  %s\n", strings.Repeat("─", 44))
	renderProfile(profile)
	fmt.Println()
	fmt.Println("Note: 'duration' measures time between consecutive tool_use")
	fmt.Println("entries — NOT pure execution time. Includes agent thinking.")
	fmt.Println("Last tool_use has 0 duration (no successor to close the span).")
}

// ----- CHUNK 2c: Session-level ToolProfile from LoadActivity -----

func demoSessionToolProfiles(ctx context.Context) {
	out, err := activity.LoadActivity(ctx, activity.LoadOpts{Scope: activity.ScopeLocal})
	if err != nil {
		fmt.Fprintln(os.Stderr, "ERROR:", err)
		return
	}

	withProfile := []activity.ActivitySession{}
	for _, s := range out.Sessions {
		if s.ToolProfile != nil && s.ToolProfile.Total > 0 {
			withProfile = append(withProfile, s)
		}
	}
	fmt.Printf("Sessions with derived ToolProfile: %d / %d\n\n",
		len(withProfile), len(out.Sessions))

	sort.Slice(withProfile, func(i, j int) bool {
		return withProfile[i].ToolProfile.Total > withProfile[j].ToolProfile.Total
	})
	for i, s := range withProfile {
		if i >= 3 {
			fmt.Printf("... and %d more\n", len(withProfile)-3)
			break
		}
		fmt.Printf("[%d] %s (active=%v, agent=%v)\n", i+1, s.SessionID, s.IsActive, s.AgentsUsed)
		fmt.Printf("    total tool uses: %d\n", s.ToolProfile.Total)
		renderProfile(s.ToolProfile)
		fmt.Println()
	}
	if len(withProfile) == 0 {
		fmt.Println("(No active sessions with a derivable transcript on disk.")
		fmt.Println(" Task 17 populates this only for sessions where IsActive=true")
		fmt.Println(" AND session.State.TranscriptPath exists.)")
	}
}

// ----- CHUNK 2d: Enrichment -----

func demoEnrichment(ctx context.Context) {
	out, err := activity.LoadActivity(ctx, activity.LoadOpts{
		Scope:         activity.ScopeCurrent,
		EnrichFromAPI: true,
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, "ERROR:", err)
		return
	}

	fmt.Printf("Source (after enrichment attempt): %s\n", out.Source)
	enrichedCheckpoints := 0
	withLabels := 0
	for _, s := range out.Sessions {
		if len(s.Labels) > 0 {
			withLabels++
		}
		for _, cp := range s.Checkpoints {
			if cp.Source == activity.SourceServer || cp.Source == activity.SourceMixed {
				enrichedCheckpoints++
			}
		}
	}
	fmt.Printf("Sessions with server labels:     %d\n", withLabels)
	fmt.Printf("Checkpoints with server data:    %d\n", enrichedCheckpoints)
	fmt.Printf("Label counts: %v\n\n", activity.LabelCounts(out.Sessions))
	fmt.Println("If all zero, either no token is configured or the server")
	fmt.Println("hasn't analyzed these checkpoints. Both paths are silent by")
	fmt.Println("design — LoadActivity never fails on enrichment errors.")
}

// ----- helpers -----

func renderProfile(p *activity.ToolProfile) {
	for _, cat := range activity.AllCategories() {
		m := p.Categories[cat]
		if m.Count == 0 && m.DurationMs == 0 {
			continue
		}
		fmt.Printf("  %-16s  %5d  %7.1fs\n", cat, m.Count, float64(m.DurationMs)/1000.0)
	}
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n-1] + "…"
}

