func main() {
	ctx := context.Background()
	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	var total, active, hasPath, fileExists, nonZero int
	var endedOrNil, missingPath, missingFile, zeroProfile int
	for _, s := range states {
		total++
		if s.EndedAt != nil {
			endedOrNil++
			continue
		}
		active++
		if s.TranscriptPath == "" {
			missingPath++
			continue
		}
		hasPath++
		f, err := os.Open(s.TranscriptPath)
		if err != nil {
			missingFile++
			continue
		}
		fileExists++
		profile, err := activity.DeriveToolTime(f)
		f.Close()
		if err != nil || profile == nil || profile.Total == 0 {
			zeroProfile++
			fmt.Printf("  zero-profile: %s agent=%s path=%s\n",
				s.SessionID[:8], string(s.AgentType), lastN(s.TranscriptPath, 40))
			continue
		}
		nonZero++
	}

	fmt.Println(strings.Repeat("─", 60))
	fmt.Printf("total sessions:           %d\n", total)
	fmt.Printf("  ended (EndedAt != nil): %d\n", endedOrNil)
	fmt.Printf("  active (EndedAt nil):   %d\n", active)
	fmt.Printf("    no TranscriptPath:    %d\n", missingPath)
	fmt.Printf("    path set:             %d\n", hasPath)
	fmt.Printf("      file missing:       %d\n", missingFile)
	fmt.Printf("      file exists:        %d\n", fileExists)
