package claudecode

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

const walkFixture = `{"type":"assistant","timestamp":"2026-04-15T10:00:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"ls -la"}}]}}
{"type":"user","timestamp":"2026-04-15T10:01:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"x"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:02:00Z","message":{"content":[{"type":"text","text":"let me think"},{"type":"tool_use","name":"Edit","input":{"file_path":"foo.go"}}]}}
{"type":"user","timestamp":"2026-04-15T10:03:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"y"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:04:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"git commit -m foo"}}]}}
`

func TestWalkToolCalls_BasicShape(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "t.jsonl")
	if err := os.WriteFile(p, []byte(walkFixture), 0o644); err != nil {
		t.Fatal(err)
	}
	calls, err := (&ClaudeCodeAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 3 {
		t.Fatalf("expected 3 calls, got %d: %+v", len(calls), calls)
	}
	if calls[0].Name != "Bash" || calls[0].BashCommand != "ls -la" {
		t.Errorf("call[0] = %+v", calls[0])
	}
	if calls[1].Name != "Edit" || calls[1].BashCommand != "" {
		t.Errorf("call[1] = %+v", calls[1])
	}
	if calls[2].Name != "Bash" || calls[2].BashCommand != "git commit -m foo" {
		t.Errorf("call[2] = %+v", calls[2])
	}
}

func TestWalkToolCalls_Timestamps(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "t.jsonl")
	if err := os.WriteFile(p, []byte(walkFixture), 0o644); err != nil {
		t.Fatal(err)
	}
	calls, err := (&ClaudeCodeAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	want0, _ := time.Parse(time.RFC3339, "2026-04-15T10:00:00Z")
	want1, _ := time.Parse(time.RFC3339, "2026-04-15T10:02:00Z")
	want2, _ := time.Parse(time.RFC3339, "2026-04-15T10:04:00Z")
	if !calls[0].Timestamp.Equal(want0) {
		t.Errorf("calls[0].Timestamp = %v, want %v", calls[0].Timestamp, want0)
	}
	if !calls[1].Timestamp.Equal(want1) {
		t.Errorf("calls[1].Timestamp = %v, want %v", calls[1].Timestamp, want1)
	}
	if !calls[2].Timestamp.Equal(want2) {
		t.Errorf("calls[2].Timestamp = %v, want %v", calls[2].Timestamp, want2)
	}
}

func TestWalkToolCalls_EmptyFile(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "empty.jsonl")
	if err := os.WriteFile(p, nil, 0o644); err != nil {
		t.Fatal(err)
	}
	calls, err := (&ClaudeCodeAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

func TestWalkToolCalls_MissingFile(t *testing.T) {
	t.Parallel()
	calls, err := (&ClaudeCodeAgent{}).WalkToolCalls("/nonexistent/path.jsonl")
	if err != nil {
		t.Errorf("missing file should be silent; got err: %v", err)
	}
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

func TestWalkToolCalls_EmptyPath(t *testing.T) {
	t.Parallel()
	calls, err := (&ClaudeCodeAgent{}).WalkToolCalls("")
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

package claudecode

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time assertion that ClaudeCodeAgent satisfies ToolCallWalker.
var _ agent.ToolCallWalker = (*ClaudeCodeAgent)(nil)

// WalkToolCalls reads Claude Code's JSONL transcript and returns one
// ToolCall per tool_use block. Missing or empty files yield (nil, nil)
// so activity-layer callers can treat absence as "no data" without
// branching on os.IsNotExist.
func (c *ClaudeCodeAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
	if path == "" {
		return nil, nil
	}
	f, err := os.Open(path) //nolint:gosec // path comes from session state written by the CLI
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("open transcript: %w", err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1<<20), 1<<24) // 16 MiB per line — tool_result payloads can be large

	type lineShape struct {
		Type      string    `json:"type"`
		Timestamp time.Time `json:"timestamp"`
		Message   struct {
			Content []struct {
				Type  string          `json:"type"`
				Name  string          `json:"name,omitempty"`
				Input json.RawMessage `json:"input,omitempty"`
			} `json:"content"`
		} `json:"message"`
	}

	var calls []agent.ToolCall
	for scanner.Scan() {
		var l lineShape
		if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
			continue
		}
		for _, block := range l.Message.Content {
			if block.Type != "tool_use" {
				continue
			}
			calls = append(calls, agent.ToolCall{
				Name:        block.Name,
				BashCommand: bashCommandFromInput(block.Input),
				Timestamp:   l.Timestamp,
			})
		}
	}
	if err := scanner.Err(); err != nil {
		return calls, fmt.Errorf("scan transcript: %w", err)
	}
	return calls, nil
}

func bashCommandFromInput(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	var v struct {
		Command string `json:"command,omitempty"`
	}
	if err := json.Unmarshal(raw, &v); err != nil {
		return ""
	}
	return v.Command
}

