// bashCommand is only inspected for shell-like tools ("Bash",
// "exec_command", "local_shell", "shell"); a `git commit`/`git push`
// command there is promoted to the virtual commit category.
//
// Recognizes both Claude Code-style CamelCase names (Bash, Edit, Grep)
// and Codex-style snake_case names (exec_command, apply_patch,
// web_search). Unrecognized names fall through to "other".
func CategorizeTool(toolName, bashCommand string) string {
	switch toolName {
	case "Bash", "exec_command", "local_shell", "shell":
		if commitCmdRe.MatchString(bashCommand) {
			return CategoryCommit
		}
		return CategoryShell
	case "Read", "Write", "Edit", "NotebookEdit",
