package activity

import (
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// DeriveToolTime computes a ToolProfile for a session's live transcript by
// dispatching to the per-agent ToolCallWalker. Returns (nil, nil) when:
//   - the agent type is unrecognized / not registered
//   - the agent does not implement ToolCallWalker (e.g. Cursor)
//   - the transcript yields zero tool calls
//
// All three are equivalent for activity rendering: no data, not an error.
// Errors are returned only for unexpected I/O failures when the walker
// itself reports one.
func DeriveToolTime(agentType types.AgentType, transcriptPath string) (*ToolProfile, error) {
	if transcriptPath == "" {
		return nil, nil
	}
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, nil //nolint:nilerr // unknown agent = no data, not an error
	}
	walker, ok := agent.AsToolCallWalker(ag)
	if !ok {
		return nil, nil
	}
	calls, err := walker.WalkToolCalls(transcriptPath)
	if err != nil {
		return nil, fmt.Errorf("walk tool calls: %w", err)
	}
	if len(calls) == 0 {
		return nil, nil
	}
	return ComputeToolProfile(calls), nil
}

// ComputeToolProfile derives a ToolProfile from an ordered sequence of
// tool calls. Pure function; safe to call from tests with synthetic
// inputs. Duration semantics: time from one tool call's timestamp to the
// next tool call's timestamp, credited to the earlier call's category.
// The final call contributes no duration (no successor to close its
// span). This is "time between tool calls", NOT execution time.
func ComputeToolProfile(calls []agent.ToolCall) *ToolProfile {
	p := &ToolProfile{Categories: map[string]ToolCategoryMetrics{}}
	for i, c := range calls {
		cat := CategorizeTool(c.Name, c.BashCommand)
		incrementCount(p, cat)
		if i+1 < len(calls) {
			if d := calls[i+1].Timestamp.Sub(c.Timestamp); d > 0 {
				addDuration(p, cat, d.Milliseconds())
			}
		}
	}
	return p
}

func incrementCount(p *ToolProfile, category string) {
	m := p.Categories[category]
	m.Count++
	p.Categories[category] = m
	p.Total++
}

func addDuration(p *ToolProfile, category string, ms int64) {
	m := p.Categories[category]
	m.DurationMs += ms
	p.Categories[category] = m
}

