// DeriveToolTime computes a ToolProfile for a session's live transcript by
// dispatching to the per-agent ToolCallWalker. Returns (nil, nil) when:
//   - the agent type is unrecognized / not registered
//   - the agent does not implement ToolCallWalker (e.g. Cursor)
//   - the transcript yields zero tool calls
//
// All three are equivalent for activity rendering: no data, not an error.
// Errors are returned only for unexpected I/O failures when the walker
// itself reports one.
func DeriveToolTime(agentType types.AgentType, transcriptPath string) (*ToolProfile, error) {
	if transcriptPath == "" {
		return nil, nil
	}
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, nil //nolint:nilerr // unknown agent = no data, not an error
	}
	walker, ok := agent.AsToolCallWalker(ag)
	if !ok {
		return nil, nil
	}
	calls, err := walker.WalkToolCalls(transcriptPath)
	if err != nil {
		return nil, fmt.Errorf("walk tool calls: %w", err)
	}
	if len(calls) == 0 {
		return nil, nil
	}
	return ComputeToolProfile(calls), nil
}

